  state_set(3, dRov); state_set(4, Mathf.sqrt(px * px + pz * pz));
}

log.source:
// Shy critter. It wanders within ROAM_M of home. When the rover comes within SCARE_M,
// it runs to the far side of the nearest rock and stays tucked there until the
// rover has been beyond SCARE_M for CALM_S seconds. It is sluggish in the cold:
// its pace scales with the live air temperature (ENV_AIR_TEMP_K, MY36 hourly-mean
// curve) between the typical nightly minimum and afternoon maximum, read with fact().
// Its energy comes from its own chemistry (player's assumption): it is active all sol.
// Player's numbers: SCARE_M, ROAM_M. Agent's suggestions, not Mars facts: HIDE_BEHIND_M,
// CALM_S, MIN_PACE, throttles, body sizes and colours.
import { read, drive, spawn, pose, log, state_set, signal_emit, mem_get, mem_set, nearest, nearest_bearing,
         fact, fact_tier, clamp, wrapAngle, POS_X, POS_Z, HEADING, SPEED, ENV_AIR_TEMP_K,
         KIND_ROVER, KIND_ROCK, SHAPE_SPHERE, FACT_JEZERO_TEMPERATURE_MY36_AIR_DIURNAL_MIN,
         FACT_JEZERO_TEMPERATURE_MY36_AIR_DIURNAL_MAX, FACT_JEZERO_TEMPERATURE_MY36_AIR_HOURLY_MEAN } from "./host";

const SCARE_M: f32 = 12.0;        // player: rover this close = too close
const ROAM_M: f32 = 10.0;         // player: wander radius around home
const HIDE_BEHIND_M: f32 = 1.5;   // agent: how far past the rock's centre it tucks in
const CALM_S: f32 = 2.0;          // agent: rover must stay away this long before it comes out
const MIN_PACE: f32 = 0.2;        // agent: fraction of top speed at the coldest
const WANDER_THROTTLE: f32 = 0.4; // agent
const HIDE_THROTTLE: f32 = 1.0;   // agent
const WANDER: i32 = 0, RUN: i32 = 1, HIDDEN: i32 = 2, FLEE: i32 = 3;
const LOG_MODE: i32 = 1;          // value: new mode (0 wander, 1 run to rock, 2 hidden, 3 flee, no rock)
const LOG_TIER: i32 = 2;          // value: provenance tier of the temperature record behind the live read
const LOG_WAYPOINT: i32 = 3;      // value: new waypoint's distance from home (m)
const SIG_SCARED: i32 = 200;      // emits 1 every tick while running or hidden

let body: i32 = -1, eyeL: i32 = -1, eyeR: i32 = -1;
let mode: i32 = WANDER, lastMode: i32 = -1;
let px: f32 = 0.0, pz: f32 = 0.0;  // dead-reckoned position relative to home (same angle convention as HEADING)
let wx: f32 = 0.0, wz: f32 = 0.0;  // current waypoint, relative to home
let calm: f32 = 0.0;
let seed: u32 = 0x9E3779B9;
let tMin: f32 = 0.0, tSpan: f32 = 0.0;

function rnd(): f32 {
  seed ^= seed << 13; seed ^= seed >> 17; seed ^= seed << 5;
  return <f32>(seed & 0xFFFFFF) / 16777216.0;
}
function newWaypoint(): void {
  const a = rnd() * 6.2831853;
  const r = ROAM_M * Mathf.sqrt(rnd());
  wx = r * Mathf.sin(a); wz = r * Mathf.cos(a);
  log(LOG_WAYPOINT, r);
}
function steerTo(bearing: f32, throttle: f32): void {
  const rel = wrapAngle(bearing - read(HEADING));
  drive(throttle * (Mathf.abs(rel) > 1.2 ? 0.3 : 1.0), clamp(rel * 1.5, -1.0, 1.0));
}
function crouch(drop: f32): void {
  pose(body, 0.0, 0.2 - drop, 0.0, 0.0, 0.0);
  pose(eyeL, -0.08, 0.3 - drop, 0.17, 0.0, 0.0);
  pose(eyeR, 0.08, 0.3 - drop, 0.17, 0.0, 0.0);
}

export function init(): void {
  body = spawn(SHAPE_SPHERE, 0.4, 0.4, 0.4, 0.75, 0.45, 0.3);
  eyeL = spawn(SHAPE_SPHERE, 0.08, 0.08, 0.08, 0.05, 0.05, 0.05);
  eyeR = spawn(SHAPE_SPHERE, 0.08, 0.08, 0.08, 0.05, 0.05, 0.05);
  crouch(0.0);
  if (mem_get(2) == 1.0) { px = mem_get(0); pz = mem_get(1); } // a reload keeps the same home
  tMin = fact(FACT_JEZERO_TEMPERATURE_MY36_AIR_DIURNAL_MIN);    // K, typical nightly minimum
  tSpan = fact(FACT_JEZERO_TEMPERATURE_MY36_AIR_DIURNAL_MAX) - tMin;
  seed ^= <u32>(<i32>(read(POS_X) * 100.0) ^ (<i32>(read(POS_Z) * 37.0)));
  if (seed == 0) seed = 1;
  log(LOG_TIER, <f32>fact_tier(FACT_JEZERO_TEMPERATURE_MY36_AIR_HOURLY_MEAN));
  newWaypoint();
}

export function tick(dt: f32): void {
  const h = read(HEADING), v = read(SPEED);
  px += v * Mathf.sin(h) * dt; pz += v * Mathf.cos(h) * dt;
  mem_set(0, px); mem_set(1, pz); mem_set(2, 1.0);
  const T = read(ENV_AIR_TEMP_K);
  let warm: f32 = 1.0;
  if (tSpan > 0.0) warm = clamp((T - tMin) / tSpan, 0.0, 1.0); // NaN span fails the test: full pace
  const pace = MIN_PACE + (1.0 - MIN_PACE) * warm;
  const x = read(POS_X), z = read(POS_Z);
  const dRov = nearest(KIND_ROVER, x, z);
  const scared = dRov >= 0.0 && dRov < SCARE_M;
  if (scared) calm = 0.0; else calm += dt;
  if (mode == WANDER && scared) mode = RUN;
  else if (mode != WANDER && calm >= CALM_S) { mode = WANDER; newWaypoint(); }

  if (mode == WANDER) {
    const dx = wx - px, dz = wz - pz;
    if (dx * dx + dz * dz < 1.0) newWaypoint();
    steerTo(Mathf.atan2(wx - px, wz - pz), WANDER_THROTTLE * pace);
  } else {
    const dRock = nearest(KIND_ROCK, x, z);
    const bV = nearest_bearing(KIND_ROVER, x, z);
    if (dRock < 0.0) { mode = FLEE; steerTo(bV + 3.14159265, HIDE_THROTTLE * pace); }
    else {
      const bR = nearest_bearing(KIND_ROCK, x, z);
      const rx = dRock * Mathf.sin(bR), rz = dRock * Mathf.cos(bR);
      const dv: f32 = dRov > 0.0 ? dRov : 0.0;
      let ux = rx - dv * Mathf.sin(bV), uz = rz - dv * Mathf.cos(bV); // rover -> rock
      const n = Mathf.sqrt(ux * ux + uz * uz);
      if (n > 0.01) { ux /= n; uz /= n; } else { ux = 0.0; uz = 1.0; }
      const hx = rx + ux * HIDE_BEHIND_M, hz = rz + uz * HIDE_BEHIND_M; // spot on the far side
      const dH = Mathf.sqrt(hx * hx + hz * hz);
      const arrive: f32 = mode == HIDDEN ? 1.5 : 0.6;
      if (dH < arrive) { mode = HIDDEN; drive(0.0, 0.0); }
      else { mode = RUN; steerTo(Mathf.atan2(hx, hz), HIDE_THROTTLE * pace); }
    }
  }

  if (mode != WANDER) signal_emit(SIG_SCARED, 1.0);
  if (mode != lastMode) { log(LOG_MODE, <f32>mode); crouch(mode == HIDDEN ? 0.1 : 0.0); lastMode = mode; }
  state_set(0, <f32>mode); state_set(1, T); state_set(2, pace);
  state_set(3, dRov); state_set(4, Mathf.sqrt(px * px + pz * pz));
}

